module alu #(
    parameter ADD = 6'b100000,
    parameter ADDU = 6'b100001,
    parameter SUB = 6'b100010,
    parameter SUBU = 6'b100011,
    parameter AND = 6'b100100,
    parameter OR = 6'b100101,
    parameter XOR = 6'b100110,
    parameter NOR = 6'b100111,
    parameter SLT = 6'b101010,
    parameter SLTU = 6'b101011,
    parameter SLL = 6'b000000,
    parameter SRL = 6'b000010,
    parameter SRA = 6'b000011,
    parameter SLLV = 6'b000100,
    parameter SRLV = 6'b000110,
    parameter SRAV = 6'b000111,
    parameter LUI = 6'b001111
) (
    input [31:0] a,
    input [31:0] b,
    input [5:0] aluc,
    output reg [31:0] r,
    output reg zero,
    output reg carry,
    output reg negative,
    output reg overflow,
    output reg flag
);

always @(*) begin
    reg [31:0] res;
    reg [31:0] sa, sb;
    sa = $signed(a);
    sb = $signed(b);
    zero = 1'b0;
    carry = 1'b0;
    negative = 1'b0;
    overflow = 1'b0;
    flag = 1'b0;

    case (aluc)
        ADD: res = sa + sb;
        ADDU: res = a + b;
        SUB: res = sa - sb;
        SUBU: res = a - b;
        AND: res = a & b;
        OR: res = a | b;
        XOR: res = a ^ b;
        NOR: res = ~(a | b);
        SLT: begin
            res = (sa < sb) ? 32'b1 : 32'b0;
            flag = (sa < sb) ? 1'b1 : 1'b0;
        end
        SLTU: begin
            res = (a < b) ? 32'b1 : 32'b0;
            flag = (a < b) ? 1'b1 : 1'b0;
        end
        SLL: res = {32'b0, a} << b[4:0];
        SRL: res = {32'b0, a} >> b[4:0];
        SRA: res = {a[31], a} >> b[4:0];
        SLLV: res = {32'b0, a} << (b & 32'h1F);
        SRLV: res = {32'b0, a} >> (b & 32'h1F);
        SRAV: res = {a[31], a} >> (b & 32'h1F);
        LUI: res = {b, 16'b0};
        default: res = 32'b0;
    endcase

    r = res;
    zero = (res == 32'b0) ? 1'b1 : 1'b0;
    negative = (res[31] == 1'b1) ? 1'b1 : 1'b0;
    overflow = ((aluc == ADD || aluc == SUB) && (sa[31] == sb[31]) && (res[31] != sa[31])) ? 1'b1 : 1'b0;
    carry = ((aluc == ADD || aluc == ADDU) && (res < a)) ? 1'b1 : 1'b0;
end

endmodule
